-- Marked disposable DB only. Auth deletion markers/factors are SQL stubs here.
begin;
create function pg_temp.retire_ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Retirement assertion: %',label;end if;end $$;
create function pg_temp.retire_denied(command text,expected text default '42501') returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate=expected then return;end if;raise exception 'Unexpected retirement SQLSTATE %',sqlstate;end;raise exception 'Expected retirement refusal';end $$;
create function pg_temp.retire_fault() returns trigger language plpgsql as $$begin raise exception 'Controlled retirement audit append failure';end $$;
do $$begin execute format('grant usage on schema %I to authenticated',pg_my_temp_schema()::regnamespace::text);end $$;
insert into auth.users(id,raw_user_meta_data) values('c1000000-0000-4000-8000-000000000001','{"display_name":"Fixture Owner"}'),('c1000000-0000-4000-8000-000000000002','{"display_name":"Identifying fixture name"}'),('c1000000-0000-4000-8000-000000000003','{"display_name":"Unaffected learner"}');
insert into auth.mfa_factors(id,user_id,factor_type,status) values('c2000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000001','totp','verified');
insert into pipstart_staff_private.members(user_id,active) values('c1000000-0000-4000-8000-000000000001',true),('c1000000-0000-4000-8000-000000000002',false);
insert into pipstart_staff_private.roles values('c1000000-0000-4000-8000-000000000001','owner');
update public.pipstart_profiles set role='admin' where user_id='c1000000-0000-4000-8000-000000000002';
update public.pipstart_email_preferences set marketing_emails=true where user_id='c1000000-0000-4000-8000-000000000002';
create table public.m22_retirement_rehearsal_history(user_id uuid references auth.users(id) on delete cascade,reference text);
insert into public.m22_retirement_rehearsal_history values('c1000000-0000-4000-8000-000000000002','retained-reference');
select pg_temp.retire_ok(not has_function_privilege('authenticated','pipstart_staff_private.account_operation_finalize_retirement(uuid,uuid,text)','EXECUTE'),'no user execution grant');
select pg_temp.retire_ok(not has_function_privilege('service_role','pipstart_staff_private.account_operation_finalize_retirement(uuid,uuid,text)','EXECUTE'),'no service-key execution grant');
do $$declare r uuid:=gen_random_uuid();d uuid;reply jsonb;begin
 perform pipstart_staff_private.account_operation_prepare(r,'c1000000-0000-4000-8000-000000000002','staff_retirement',null,null,'staff_retirement',0);
 reply:=pipstart_staff_private.account_operation_claim(r);d:=(reply->>'dispatch_id')::uuid;
 perform pg_temp.retire_denied(format('select pipstart_staff_private.account_operation_finalize_retirement(%L,%L,%L)',r,d,'succeeded'));
 update auth.users set deleted_at=clock_timestamp() where id='c1000000-0000-4000-8000-000000000002';
 perform pg_temp.retire_denied(format('select pipstart_staff_private.account_operation_finalize_retirement(%L,%L,%L)',r,gen_random_uuid(),'succeeded'),'22023');
 perform pg_temp.retire_denied(format('select pipstart_staff_private.account_operation_finalize_retirement(%L,%L,%L)',r,d,'observed_desired'));
 update pipstart_staff_private.members set active=false where user_id='c1000000-0000-4000-8000-000000000001';
 perform pg_temp.retire_denied(format('select pipstart_staff_private.account_operation_finalize_retirement(%L,%L,%L)',r,d,'succeeded'));
 update pipstart_staff_private.members set active=true where user_id='c1000000-0000-4000-8000-000000000001';
 insert into pipstart_staff_private.assignments values('c1000000-0000-4000-8000-000000000002','lesson','retirement-block');
 perform pg_temp.retire_denied(format('select pipstart_staff_private.account_operation_finalize_retirement(%L,%L,%L)',r,d,'succeeded'));
 delete from pipstart_staff_private.assignments where user_id='c1000000-0000-4000-8000-000000000002';
 execute 'create trigger m22_retirement_append_fault before insert on pipstart_staff_private.account_operation_events for each row execute function pg_temp.retire_fault()';
 perform pg_temp.retire_denied(format('select pipstart_staff_private.account_operation_finalize_retirement(%L,%L,%L)',r,d,'succeeded'),'P0001');
 perform pg_temp.retire_ok((select display_name='Identifying fixture name' and role::text='admin' from public.pipstart_profiles where user_id='c1000000-0000-4000-8000-000000000002'),'audit failure rolls profile back');
 perform pg_temp.retire_ok((select educational_emails and marketing_emails from public.pipstart_email_preferences where user_id='c1000000-0000-4000-8000-000000000002'),'audit failure rolls preferences back');
 perform pg_temp.retire_ok((select status='dispatched' from pipstart_staff_private.account_operations where request_id=r),'audit failure leaves journal pending');
 execute 'drop trigger m22_retirement_append_fault on pipstart_staff_private.account_operation_events';
 reply:=pipstart_staff_private.account_operation_finalize_retirement(r,d,'succeeded');
 perform pg_temp.retire_ok(reply->>'status'='finalized','local finalization acknowledged');
 perform pg_temp.retire_ok(pipstart_staff_private.account_operation_finalize_retirement(r,d,'succeeded')->>'status'='already_finalized','repeat is readback only');
 perform pg_temp.retire_ok((select display_name='Former staff member' and role::text='learner' from public.pipstart_profiles where user_id='c1000000-0000-4000-8000-000000000002'),'profile pseudonymized and legacy flag cleared');
 perform pg_temp.retire_ok((select not educational_emails and not marketing_emails from public.pipstart_email_preferences where user_id='c1000000-0000-4000-8000-000000000002'),'optional email disabled');
 perform pg_temp.retire_ok((select count(*)=1 from public.m22_retirement_rehearsal_history),'retained reference survives');
 perform pg_temp.retire_denied($q$delete from auth.users where id='c1000000-0000-4000-8000-000000000002'$q$,'23503');
end $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"c1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select pg_temp.retire_denied($q$update public.pipstart_profiles set display_name='Revived identifying name' where user_id='c1000000-0000-4000-8000-000000000002'$q$);
select pg_temp.retire_denied($q$update public.pipstart_email_preferences set educational_emails=true where user_id='c1000000-0000-4000-8000-000000000002'$q$);
reset role;
update public.pipstart_profiles set display_name='Learner remains editable' where user_id='c1000000-0000-4000-8000-000000000003';
select pg_temp.retire_ok((select display_name='Learner remains editable' from public.pipstart_profiles where user_id='c1000000-0000-4000-8000-000000000003'),'unaffected learner profile');
select pg_temp.retire_ok(not (select enabled from pipstart_staff_private.control),'staff stays paused');
rollback;
